      // validate its ASCII prefix and the first high-bit byte.
      return validate_utf8_scalar(bytes + index, length - index);
    }
    index += 16;
  }
  if (index == length) {
    return true;
  }
  return validate_utf8_scalar(bytes + index, length - index);
#else
  return validate_utf8_scalar(bytes, length);
#endif
}

